/*Table structure for table `accounts` */

DROP TABLE IF EXISTS `accounts`;

CREATE TABLE `accounts` (
  `id` INT(10) UNSIGNED NOT NULL AUTO_INCREMENT,
  `type` ENUM('buyer','supplier') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'buyer',
  `name` VARCHAR(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  `contact_person` VARCHAR(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `phone` VARCHAR(50) COLLATE utf8mb4_unicode_ci NOT NULL,
  `address` TEXT COLLATE utf8mb4_unicode_ci,
  `credit_limit` DECIMAL(12,2) NOT NULL DEFAULT '0.00',
  `payment_terms` VARCHAR(50) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'Cash',
  `opening_balance` DECIMAL(12,2) NOT NULL DEFAULT '0.00',
  `current_balance` DECIMAL(12,2) NOT NULL DEFAULT '0.00',
  `id_or_permit_number` VARCHAR(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `status` ENUM('pending','approved','rejected') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'pending',
  `notes` TEXT COLLATE utf8mb4_unicode_ci,
  `approved_at` TIMESTAMP NULL DEFAULT NULL,
  `approved_by` INT(10) UNSIGNED DEFAULT NULL,
  `created_at` TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `idx_accounts_type` (`type`),
  KEY `idx_accounts_status` (`status`),
  KEY `idx_accounts_name` (`name`)
) ENGINE=INNODB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

