/*Table structure for table `inventory_disposals` */

DROP TABLE IF EXISTS `inventory_disposals`;

CREATE TABLE `inventory_disposals` (
  `id` INT(10) UNSIGNED NOT NULL AUTO_INCREMENT,
  `inventory_id` INT(10) UNSIGNED NOT NULL,
  `batch_no` VARCHAR(50) NOT NULL,
  `product_id` INT(10) UNSIGNED NOT NULL,
  `product_name` VARCHAR(255) NOT NULL,
  `meat_cut` VARCHAR(100) DEFAULT NULL,
  `weight_disposed_kg` DECIMAL(10,3) NOT NULL,
  `disposed_by` INT(10) UNSIGNED DEFAULT NULL,
  `disposed_by_name` VARCHAR(255) DEFAULT NULL,
  `reason` VARCHAR(255) DEFAULT 'Expired stock disposal',
  `created_at` TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `idx_inventory_id` (`inventory_id`),
  KEY `idx_product_id` (`product_id`),
  KEY `idx_created_at` (`created_at`)
) ENGINE=INNODB AUTO_INCREMENT=3 DEFAULT CHARSET=latin1;

/*Data for the table `inventory_disposals` */

INSERT  INTO `inventory_disposals`(`id`,`inventory_id`,`batch_no`,`product_id`,`product_name`,`meat_cut`,`weight_disposed_kg`,`disposed_by`,`disposed_by_name`,`reason`,`created_at`) VALUES (1,45,'DEMO-LOW-5-614',5,'Beef Tenderloin (Filet Mignon)','Tenderloin','3.500',1,'Admin SMIS','Expired inventory routine disposal','2026-10-21 05:26:03'),(2,100,'B-20261021-397',10,'Beef Brisket Point & Flat','Brisket','100.000',1,'Admin SMIS','Expired inventory routine disposal','2026-10-21 05:26:47');

/*Table structure for table `order_items` */

DROP TABLE IF EXISTS `order_items`;

CREATE TABLE `order_items` (
  `id` INT(10) UNSIGNED NOT NULL AUTO_INCREMENT,
  `order_id` INT(10) UNSIGNED NOT NULL,
  `product_id` INT(10) UNSIGNED NOT NULL,
  `product_name` VARCHAR(255) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'Snapshot at time of order',
  `meat_cut` VARCHAR(100) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'Snapshot at time of order',
  `weight_kg` DECIMAL(10,3) NOT NULL,
  `price_per_kg` DECIMAL(10,2) NOT NULL,
  `subtotal` DECIMAL(10,2) NOT NULL,
  `created_at` TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `idx_order_items_order` (`order_id`),
  KEY `idx_order_items_product` (`product_id`),
  CONSTRAINT `fk_order_items_order` FOREIGN KEY (`order_id`) REFERENCES `orders` (`id`) ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT `fk_order_items_product` FOREIGN KEY (`product_id`) REFERENCES `products` (`id`) ON UPDATE CASCADE
) ENGINE=INNODB AUTO_INCREMENT=88 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

