/*Table structure for table `products` */

DROP TABLE IF EXISTS `products`;

CREATE TABLE `products` (
  `id` INT(10) UNSIGNED NOT NULL AUTO_INCREMENT,
  `category_id` INT(10) UNSIGNED NOT NULL,
  `name` VARCHAR(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  `meat_type` VARCHAR(100) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'e.g., Beef, Pork, Chicken',
  `meat_cut` VARCHAR(100) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'e.g., Liempo, Kasim, Buto, Pigue',
  `price_per_kg` DECIMAL(10,2) NOT NULL COMMENT 'Base retail price per kilogram',
  `low_stock_threshold` DECIMAL(10,3) NOT NULL DEFAULT '15.000',
  `description` TEXT COLLATE utf8mb4_unicode_ci,
  `image_url` VARCHAR(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `is_active` TINYINT(1) NOT NULL DEFAULT '1',
  `created_at` TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `idx_products_category` (`category_id`),
  KEY `idx_products_meat_type` (`meat_type`),
  CONSTRAINT `fk_products_category` FOREIGN KEY (`category_id`) REFERENCES `categories` (`id`) ON UPDATE CASCADE
) ENGINE=INNODB AUTO_INCREMENT=45 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

