/*Table structure for table `sales` */

DROP TABLE IF EXISTS `sales`;

CREATE TABLE `sales` (
  `id` INT(10) UNSIGNED NOT NULL AUTO_INCREMENT,
  `cashier_id` INT(10) UNSIGNED NOT NULL COMMENT 'FK to users (role=cashier)',
  `customer_id` INT(10) UNSIGNED DEFAULT NULL COMMENT 'FK to customers — NULL for walk-in',
  `receipt_no` VARCHAR(50) COLLATE utf8mb4_unicode_ci NOT NULL,
  `subtotal` DECIMAL(10,2) NOT NULL DEFAULT '0.00',
  `discount` DECIMAL(10,2) NOT NULL DEFAULT '0.00',
  `total_amount` DECIMAL(10,2) NOT NULL DEFAULT '0.00',
  `payment_method` ENUM('cash','gcash','card','other') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'cash',
  `amount_tendered` DECIMAL(10,2) NOT NULL DEFAULT '0.00',
  `change_amount` DECIMAL(10,2) NOT NULL DEFAULT '0.00',
  `notes` TEXT COLLATE utf8mb4_unicode_ci,
  `created_at` TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_sales_receipt` (`receipt_no`),
  KEY `idx_sales_cashier` (`cashier_id`),
  KEY `idx_sales_customer` (`customer_id`),
  KEY `idx_sales_created_at` (`created_at`),
  CONSTRAINT `fk_sales_cashier` FOREIGN KEY (`cashier_id`) REFERENCES `users` (`id`) ON UPDATE CASCADE,
  CONSTRAINT `fk_sales_customer` FOREIGN KEY (`customer_id`) REFERENCES `customers` (`id`) ON DELETE SET NULL ON UPDATE CASCADE
) ENGINE=INNODB AUTO_INCREMENT=107 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

