/*Table structure for table `sales_items` */

DROP TABLE IF EXISTS `sales_items`;

CREATE TABLE `sales_items` (
  `id` INT(10) UNSIGNED NOT NULL AUTO_INCREMENT,
  `sale_id` INT(10) UNSIGNED NOT NULL,
  `inventory_id` INT(10) UNSIGNED NOT NULL COMMENT 'Which batch was deducted',
  `product_id` INT(10) UNSIGNED NOT NULL,
  `product_name` VARCHAR(255) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'Snapshot at time of sale',
  `meat_cut` VARCHAR(100) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'Snapshot at time of sale',
  `weight_kg` DECIMAL(10,3) NOT NULL,
  `price_per_kg` DECIMAL(10,2) NOT NULL,
  `subtotal` DECIMAL(10,2) NOT NULL,
  `created_at` TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `idx_sales_items_sale` (`sale_id`),
  KEY `idx_sales_items_inventory` (`inventory_id`),
  KEY `idx_sales_items_product` (`product_id`),
  CONSTRAINT `fk_sales_items_inventory` FOREIGN KEY (`inventory_id`) REFERENCES `inventory` (`id`) ON UPDATE CASCADE,
  CONSTRAINT `fk_sales_items_product` FOREIGN KEY (`product_id`) REFERENCES `products` (`id`) ON UPDATE CASCADE,
  CONSTRAINT `fk_sales_items_sale` FOREIGN KEY (`sale_id`) REFERENCES `sales` (`id`) ON DELETE CASCADE ON UPDATE CASCADE
) ENGINE=INNODB AUTO_INCREMENT=241 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

