/*Table structure for table `suppliers` */

DROP TABLE IF EXISTS `suppliers`;

CREATE TABLE `suppliers` (
  `id` INT(10) UNSIGNED NOT NULL AUTO_INCREMENT,
  `name` VARCHAR(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  `contact_person` VARCHAR(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `phone` VARCHAR(30) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `email` VARCHAR(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `address` TEXT COLLATE utf8mb4_unicode_ci,
  `is_active` TINYINT(1) NOT NULL DEFAULT '1',
  `created_at` TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `idx_suppliers_name` (`name`)
) ENGINE=INNODB AUTO_INCREMENT=3 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

/*Data for the table `suppliers` */

INSERT  INTO `suppliers`(`id`,`name`,`contact_person`,`phone`,`email`,`address`,`is_active`,`created_at`,`updated_at`) VALUES (1,'San Jose Slaughterhouse & Livestock','Carlos Mendoza','09179998888','sanjose@livestock.ph','Bulacan, Philippines',1,'2026-08-03 00:11:09','2026-08-03 00:11:09'),(2,'jeffrey','jeffrey peresores','12345678910','jeff@gmail.com',NULL,1,'2026-08-06 20:33:29','2026-08-06 20:33:29');

/*Table structure for table `users` */

DROP TABLE IF EXISTS `users`;

CREATE TABLE `users` (
  `id` INT(10) UNSIGNED NOT NULL AUTO_INCREMENT,
  `first_name` VARCHAR(100) COLLATE utf8mb4_unicode_ci NOT NULL,
  `last_name` VARCHAR(100) COLLATE utf8mb4_unicode_ci NOT NULL,
  `email` VARCHAR(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `password_hash` VARCHAR(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `role` VARCHAR(50) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'customer',
  `status` ENUM('pending','active','rejected') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'pending',
  `is_active` TINYINT(1) NOT NULL DEFAULT '1',
  `is_temp_password` TINYINT(1) NOT NULL DEFAULT '0',
  `temp_password_plain` VARCHAR(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `profile_picture` LONGTEXT COLLATE utf8mb4_unicode_ci,
  `created_at` TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `username` VARCHAR(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `deleted_at` TIMESTAMP NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_users_email` (`email`),
  UNIQUE KEY `uq_users_username` (`username`),
  KEY `idx_users_role` (`role`)
) ENGINE=INNODB AUTO_INCREMENT=55 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

/*Data for the table `users` */

